export const DRAWING_PROMPTS=['Invent a tiny robot with an unexpected job.','Draw a floating island and the creature who lives there.','Design a friendly monster café menu.','Make a map to a secret treehouse.','Draw a space garden with three impossible plants.','Together: one artist draws a home, the other adds its visitors.'];
export const TOOL_GUIDES={pencil:'Fine lines for details and sketches.',marker:'Layer translucent strokes to build color.',brush:'Soft strokes. Try a large brush for the background.',spray:'Drag slowly for a denser spray of color.',eraser:'Erase drawing strokes; layers stay movable.',fill:'Tap an enclosed area to fill it with your color.',line:'Drag from the start to the end of your line.',circle:'Drag across the width and height of your oval.',rect:'Drag between opposite corners of a rectangle.',triangle:'Drag to size your triangle.',star:'Drag outward from the center of your star.',select:'Drag a layer to move it; use two fingers to resize and rotate.'};
export function patternSummary(pattern){const count=pattern.matrix.reduce((sum,row)=>sum+row.slice(0,pattern.steps).filter(Boolean).length,0),tracks=pattern.matrix.filter(row=>row.slice(0,pattern.steps).some(Boolean)).length;return{count,tracks,text:count?`${count} notes · ${tracks} active tracks · ${pattern.steps/4} beats`:'Start with a preset, or tap a step to add your first note.'};}
